// Module: calc-repair-quest.js
    window.panelExportConfig = window.panelExportConfig || {
      paid_access: true,
      enforcePaidAccess: false,
      proMessage: 'Экспорт и печать щита доступны при разовой оплате или по подписке'
    };

    // Repair quest rendering can be heavy (large innerHTML). Schedule it to avoid
    // re-render storms on each keystroke/click.
    let repairQuestRenderScheduled = false;

    function scheduleRepairQuestRender() {
      if (!repairQuestState?.active) return;
      if (repairQuestRenderScheduled) return;
      repairQuestRenderScheduled = true;
      requestAnimationFrame(() => {
        repairQuestRenderScheduled = false;
        renderRepairQuest();
      });
    }

    window.refreshRepairQuestRoomRepairScopes = function refreshRepairQuestRoomRepairScopes() {
      if (!repairQuestState?.answers) return;
      Object.values(repairQuestState.answers).forEach(answer => {
        if (!answer || answer.electricalPanelHere !== 'yes') return;
        answer.electricalPanelValidationChecked = 'no';
        answer.electricalPanelValidationRisks = [];
        answer.electricalPanelCalcConfirmed = 'no';
      });
      scheduleRepairQuestRender();
    };

    function afterNextPaint(cb) {
      requestAnimationFrame(() => requestAnimationFrame(cb));
    }

    function ensureRepairQuestConfettiGenerated() {
      if (!repairQuestState) return;
      if (typeof repairQuestState.confettiHtml === 'string' && repairQuestState.confettiHtml.length) return;
      const colors = ['#f59e0b', '#fb7185', '#38bdf8', '#34d399', '#8b5cf6', '#f97316'];
      repairQuestState.confettiHtml = Array.from({ length: 20 }, (_, index) => {
        const left = Math.round(Math.random() * 90);
        const size = 6 + Math.round(Math.random() * 8);
        const delay = (Math.random() * 0.8).toFixed(2);
        return `<span class="confetti" style="left:${left}%; width:${size}px; height:${size}px; background:${colors[index % colors.length]}; animation-delay:${delay}s"></span>`;
      }).join('');
    }

