    function resetRepairQuestBlockConfirmation(roomKey, field) {
      const answer = repairQuestState.answers[roomKey];
      if (!answer) return;
      if (!answer.blockConfirmation) {
        answer.blockConfirmation = getRepairQuestEmptyBlockConfirmation();
      }
      const map = getRepairQuestFieldBlockMap();
      const blockKey = map[field];
      if (blockKey) answer.blockConfirmation[blockKey] = false;
      if (Array.isArray(answer.acceptedRiskIds)) {
        answer.acceptedRiskIds = [];
      }
      if (['smartHome', 'smartCurtains', 'smartLeakSensors', 'smartLightOffSensors', 'smartMotionSensors', 'smartClimateSensors', 'smartTempHumiditySensors', 'smartPresenceSensors', 'smartDoorSensors', 'smartIlluminanceSensors', 'smartGasSensors', 'smartCoSensors', 'smartSmokeSensors', 'smartAirQualitySensors', 'smartPanelSeparateLine', 'smartPanelUps', 'smartPanelSurgeProtection', 'smartPanelDifProtection', 'smartPanelReservePercent', 'smartPanelPowerSupplies', 'smartPanelRelayModules', 'smartPanelGroupBreakers', 'entrySecurityMode', 'securityLevel', 'securityCameraCount', 'securityCameraType', 'securityDoorOpening', 'securityRecorder', 'securitySmartSensors'].includes(field)) {
        answer.blockConfirmation.electricalPanel = false;
        answer.blockConfirmation.smartPanel = false;
      }
      if (field === 'distanceToElectricalPanel') {
        answer.blockConfirmation.electricalLighting = false;
        answer.blockConfirmation.electricalSockets = false;
        answer.blockConfirmation.climate = false;
      }
      if (['ledLinesLength', 'wallLinearLightLength', 'ceilingBacklightLength', 'plinthBacklightLength', 'spotLights', 'chandeliers', 'wallLights', 'floorLights', 'trackLights', 'nightLightPoints', 'motionLightSensors', 'motionLightTarget', 'electricalScope', 'electricalWorkScope', 'singleSockets', 'doubleSockets', 'tripleSockets', 'moistureProofSockets', 'singleSwitches', 'doubleSwitches', 'tripleSwitches', 'masterLightSwitches', 'masterPowerSwitches', 'generalMasterSwitch', 'internetSocket', 'internetPoints', 'tvSocket', 'tvPoints', 'fireProtection', 'fireSmokeDetectors', 'fireCoDetectors', 'climateScope', 'acSystemType', 'ventilationSystem', 'acUnits', 'warmFloor', 'warmFloorType'].includes(field)) {
        answer.blockConfirmation.electricalPanel = false;
      }
      if (['ledLinesLength', 'ceilingBacklightLength', 'ceilingBacklightNicheLength', 'ceilingBacklightFullPerimeter', 'ceilingLightSpots', 'ceilingLightLines', 'ceilingLightPendants', 'ceilingLightTracks', 'ceilingLightHidden', 'trackLights', 'ceilingTrackLength', 'ceilingCurtainNicheLength', 'ceilingGkBoxLength', 'ceilingGkBoxHeight'].includes(field)) {
        answer.blockConfirmation.finishCeiling = false;
        answer.blockConfirmation.electricalLighting = false;
      }
      if (['wallLightSconces', 'wallLightLinear', 'wallLights', 'wallLinearLightLength'].includes(field)) {
        answer.blockConfirmation.finishWall = false;
        answer.blockConfirmation.electricalLighting = false;
      }
      if (['floorLightPlinthBacklight', 'floorLightInFloor', 'plinthBacklightLength', 'floorLights'].includes(field)) {
        answer.blockConfirmation.finishFloor = false;
        answer.blockConfirmation.electricalLighting = false;
      }
      if (field === 'currentState' && answer.currentState !== 'old_finish') {
        answer.blockConfirmation.demolition = false;
        answer.blockConfirmation.finishDemolition = false;
      }
      if (['currentState', 'replanningAction', 'roughWallPlan'].includes(field)) {
        answer.blockConfirmation.partitionDemolition = false;
        answer.blockConfirmation.partitionBuild = false;
        answer.blockConfirmation.replanning = false;
      }
      if (field === 'plumbingScope') {
        answer.blockConfirmation.water = false;
        answer.blockConfirmation.drainage = false;
      }
    }

    function confirmRepairQuestBlock(roomKey, blockKey) {
      const answer = repairQuestState.answers[roomKey];
      if (!answer) return;
      const validation = validateRepairQuestBlockBeforeConfirm(roomKey, blockKey);
      if (!validation.ok) {
        alert(validation.message);
        return;
      }
      if (!isRepairQuestBlockReady(roomKey, blockKey)) {
        alert('Сначала заполните этот блок, затем подтвердите выбор.');
        return;
      }
      if (!answer.blockConfirmation) {
        answer.blockConfirmation = getRepairQuestEmptyBlockConfirmation();
      }
      const wasConfirmed = !!answer.blockConfirmation[blockKey];
      answer.blockConfirmation[blockKey] = true;
      if (!wasConfirmed) {
        repairQuestState.lastConfirmedBlock = { roomKey, blockKey, timestamp: Date.now() };
      }
      scheduleRepairQuestRender();
    }

    function validateRepairQuestBlockBeforeConfirm(roomKey, blockKey) {
      const answer = repairQuestState.answers[roomKey];
      if (!answer) return { ok: false, message: 'Не удалось найти ответы по этой комнате.' };
      if (blockKey === 'electricalLighting' && shouldRequireRepairQuestPanelDistance(answer)) {
        return {
          ok: false,
          message: 'Заполните поле «Сколько метров до электрощита от входа в помещение», затем подтвердите организацию света.'
        };
      }
      return { ok: true, message: '' };
    }

    function shouldRequireRepairQuestPanelDistance(answer = {}) {
      return answer.electricalPanelHere !== 'yes'
        && answer.electricalScope !== 'no_touch'
        && Number(answer.distanceToElectricalPanel || 0) <= 0;
    }

    function confirmReadyRepairQuestBlocks(roomKey) {
      const answer = repairQuestState.answers[roomKey];
      const meta = repairQuestState.rooms.find(room => room.key === roomKey);
      if (!answer || !meta) return;
      if (!answer.blockConfirmation) {
        answer.blockConfirmation = getRepairQuestEmptyBlockConfirmation();
      }
      getRepairQuestBlockKeys(meta).forEach(blockKey => {
        if (validateRepairQuestBlockBeforeConfirm(roomKey, blockKey).ok && isRepairQuestBlockReady(roomKey, blockKey)) {
          answer.blockConfirmation[blockKey] = true;
        }
      });
      scheduleRepairQuestRender();
    }

    function confirmAllRepairQuestDefaults() {
      repairQuestState.rooms.forEach(room => {
        const answer = repairQuestState.answers[room.key];
        if (!answer) return;
        if (!answer.blockConfirmation) {
          answer.blockConfirmation = getRepairQuestEmptyBlockConfirmation();
        }
        getRepairQuestBlockKeys(room).forEach(blockKey => {
          if (validateRepairQuestBlockBeforeConfirm(room.key, blockKey).ok && isRepairQuestBlockReady(room.key, blockKey)) {
            answer.blockConfirmation[blockKey] = true;
          }
        });
      });
      scheduleRepairQuestRender();
    }

    function isRepairQuestBlockConfirmed(roomKey, blockKey) {
      return !!repairQuestState.answers[roomKey]?.blockConfirmation?.[blockKey];
    }

    function getRepairQuestConfirmedBlocks() {
      return repairQuestState.rooms.reduce((sum, room) => sum + getRepairQuestBlockKeys(room).filter(block => isRepairQuestBlockConfirmed(room.key, block)).length, 0);
    }

    function getRepairQuestTotalBlocks() {
      return repairQuestState.rooms.reduce((sum, room) => sum + getRepairQuestBlockKeys(room).length, 0);
    }

    function updateRepairQuestCounter(roomKey, field, delta, minValue = 0, maxValue = 25) {
      const answer = repairQuestState.answers[roomKey];
      if (!answer) return;
      let nextValue = (parseInt(answer[field], 10) || 0) + delta;
      nextValue = Math.max(minValue, Math.min(maxValue, nextValue));
      answer[field] = nextValue;
      syncRepairQuestMiterLengthsAfterCounterChange(roomKey, field);
      synchronizeRepairQuestDerivedFields(roomKey, field);
      resetRepairQuestBlockConfirmation(roomKey, field);
      scheduleRepairQuestRender();
    }

    function setRepairQuestCounter(roomKey, field, value, minValue = 0, maxValue = 25) {
      const answer = repairQuestState.answers[roomKey];
      if (!answer) return;
      let nextValue = parseInt(value, 10);
      if (!Number.isFinite(nextValue)) nextValue = minValue;
      answer[field] = Math.max(minValue, Math.min(maxValue, nextValue));
      syncRepairQuestMiterLengthsAfterCounterChange(roomKey, field);
      synchronizeRepairQuestDerivedFields(roomKey, field);
      resetRepairQuestBlockConfirmation(roomKey, field);
      scheduleRepairQuestRender();
    }

    function setRepairQuestNumber(roomKey, field, value, minValue = 0, maxValue = 9999) {
      const answer = repairQuestState.answers[roomKey];
      if (!answer) return;
      let nextValue = parseFloat(String(value).replace(',', '.'));
      if (!Number.isFinite(nextValue)) nextValue = minValue;
      answer[field] = Number(Math.max(minValue, Math.min(maxValue, nextValue)).toFixed(2));
      if (field === 'partitionDemoLength' && answer[field] > 0) answer.partitionDemoArea = 0;
      if (field === 'partitionDemoArea' && answer[field] > 0) answer.partitionDemoLength = 0;
      if (field === 'partitionBuildLength' && answer[field] > 0) answer.partitionBuildArea = 0;
      if (field === 'partitionBuildArea' && answer[field] > 0) answer.partitionBuildLength = 0;
      synchronizeRepairQuestDerivedFields(roomKey, field);
      resetRepairQuestBlockConfirmation(roomKey, field);
      scheduleRepairQuestRender();
    }

    function setRepairQuestNumberDraft(roomKey, field, value, minValue = 0, maxValue = 9999) {
      const answer = repairQuestState.answers[roomKey];
      if (!answer) return;
      const raw = String(value ?? '').replace(',', '.');
      if (!raw.trim()) {
        answer[field] = 0;
        return;
      }
      let nextValue = parseFloat(raw);
      if (!Number.isFinite(nextValue)) return;
      answer[field] = Number(Math.max(minValue, Math.min(maxValue, nextValue)).toFixed(2));
      if (field === 'partitionDemoLength' && answer[field] > 0) answer.partitionDemoArea = 0;
      if (field === 'partitionDemoArea' && answer[field] > 0) answer.partitionDemoLength = 0;
      if (field === 'partitionBuildLength' && answer[field] > 0) answer.partitionBuildArea = 0;
      if (field === 'partitionBuildArea' && answer[field] > 0) answer.partitionBuildLength = 0;
    }

    function setRepairQuestMiterCornerLength(roomKey, field, index, value) {
      const answer = repairQuestState.answers[roomKey];
      if (!answer) return;
      const nextIndex = Math.max(0, parseInt(index, 10) || 0);
      const lengths = Array.isArray(answer[field]) ? [...answer[field]] : [];
      let nextValue = parseFloat(String(value).replace(',', '.'));
      if (!Number.isFinite(nextValue)) nextValue = 0;
      lengths[nextIndex] = Number(Math.max(0, Math.min(20, nextValue)).toFixed(2));
      answer[field] = lengths;
      resetRepairQuestBlockConfirmation(roomKey, field);
      scheduleRepairQuestRender();
    }

    function goRepairQuestStep(delta) {
      const maxStep = repairQuestState.rooms.length;
      const previousStep = repairQuestState.step;
      repairQuestState.step = Math.max(0, Math.min(maxStep, repairQuestState.step + delta));
      if (repairQuestState.step !== previousStep) {
        repairQuestState.scrollToRoomTop = true;
      }
      scheduleRepairQuestRender();
    }

    function getRepairQuestStepCompletion(stepIndex = repairQuestState.step) {
      const meta = repairQuestState.rooms[stepIndex];
      if (!meta) return 1;
      const answer = repairQuestState.answers[meta.key];
      if (!answer) return 0;
      const blockKeys = getRepairQuestBlockKeys(meta);
      const confirmed = blockKeys.filter(blockKey => isRepairQuestBlockConfirmed(meta.key, blockKey)).length;
      return blockKeys.length ? confirmed / blockKeys.length : 1;
    }

    function getRepairQuestOverallProgress() {
      const totalBlocks = getRepairQuestTotalBlocks();
      if (!totalBlocks) return 0;
      return Math.min(1, getRepairQuestConfirmedBlocks() / totalBlocks);
    }

    function hasRepairQuestAnswerValue(value) {
      return Array.isArray(value) ? value.length > 0 : value !== '' && value !== null && value !== undefined;
    }

    function getRepairQuestDisplayedEquipmentFields(meta) {
      const all = getRepairQuestEquipmentConfigs(meta).map(config => config.field);
      if (repairQuestState.mode === 'full') return all;

      // Approx: keep only the few answers that materially shift counts/cost.
      const roomType = getRepairQuestNormalizedRoomType(meta);
      const rules = getRepairQuestContextRules(meta, repairQuestState.answers?.[meta.key] || {});
      const addContextFields = fields => {
        const next = fields.filter(field => all.includes(field));
        if (rules.recommendSecurity && all.includes('entrySecurityMode') && !next.includes('entrySecurityMode')) next.push('entrySecurityMode');
        return next;
      };
      if (roomType === 'kitchen') {
        return addContextFields(['kitchenLayout', 'stoveType', 'dishwasher', 'oven', 'fridgeInstallation', 'hoodType', 'disposer', 'applianceLoad']);
      }
      if (['shower', 'bathroom', 'toilet', 'combined_bath', 'laundry', 'pool', 'spa', 'sauna'].includes(roomType)) {
        return addContextFields(['bathroomFixture', 'showerTrayMode', 'showerTrayMaterial', 'showerTrayTileMaterial', 'washingMachine', 'boilerOption', 'towelDryer']);
      }
      if (roomType === 'boiler_room') {
        return addContextFields(['boilerOption', 'entrySecurityMode', 'intercomType', 'securityLevel']);
      }
      if (roomType === 'garage') {
        return addContextFields(['entrySecurityMode', 'intercomType', 'securityLevel']);
      }
      if (roomType === 'office') {
        return addContextFields(['workPlaces', 'entrySecurityMode', 'intercomType', 'securityLevel']);
      }
      if (['hallway', 'hall', 'corridor', 'wardrobe', 'storage'].includes(roomType)) {
        return addContextFields(['entrySecurityMode', 'intercomType', 'securityLevel']);
      }
      if (roomType === 'living_room') {
        return addContextFields(['acoustics']);
      }
      return addContextFields([]);
    }

    function getRepairQuestDisplayedElectricalScenarioFields(meta, answer = repairQuestState.answers?.[meta?.key] || {}) {
      const fields = getRepairQuestElectricalScenarioConfigs(meta, answer).map(config => config.field);
      return fields;
    }

    function isRepairQuestWallElectricalScenarioField(field) {
      return ['extraSockets', 'workPlaces', 'workPlace'].includes(field);
    }

    function getRepairQuestDisplayedSurfaceFields(meta, answer) {
      if (!shouldShowRepairQuestFinishingBlock(answer)) return [];
      const fields = ['targetFloor', 'targetWall', 'targetCeiling'];
      if (repairQuestState.mode === 'full') {
        fields.push('backsplash');
      } else if (isRepairQuestKitchenRoom(meta)) {
        fields.push('backsplash');
      }
      return fields;
    }

    function getRepairQuestDisplayedFinishFloorFields(answer) {
      if (!shouldShowRepairQuestFinishingBlock(answer)) return [];
      const fields = ['targetFloor', 'targetFloorDetail'];
      if (repairQuestState.mode === 'full' && shouldShowRepairQuestFloorCoverSize(answer)) {
        if (isRepairQuestStructuredFloorCoverTarget(answer)) fields.push('floorCoverShape', 'floorCoverFormat');
        fields.push('floorCoverLengthMm', 'floorCoverWidthMm');
        if (isRepairQuestStructuredFloorCoverTarget(answer)) fields.push('targetFloorLayout');
      }
      if (repairQuestState.mode === 'full' && isRepairQuestFloorTileTarget(answer)) {
        fields.push('floorTileShape', 'floorTileFormat', 'targetFloorLayout', 'targetFloorMiterEnabled', 'targetFloorMosaicEnabled', 'targetFloorBorderEnabled', 'targetFloorDecorEnabled');
        if (answer.targetFloorBorderEnabled === 'yes') fields.push('targetFloorBorderFullPerimeter', 'targetFloorBorderLength', 'targetFloorBorderElementLengthMm', 'targetFloorBorderWidthMm');
        if (answer.targetFloorDecorEnabled === 'yes') fields.push('targetFloorDecorCount', 'targetFloorDecorLengthMm', 'targetFloorDecorWidthMm');
      }
      if (repairQuestState.mode === 'full') fields.push('floorLightPlinthBacklight', 'floorLightInFloor');
      return fields;
    }

    function getRepairQuestDisplayedFinishWallFields(meta, answer) {
      if (!shouldShowRepairQuestFinishingBlock(answer)) return [];
      const fields = ['targetWall'];
      if (isRepairQuestKitchenRoom(meta)) fields.push('backsplash');
      if (repairQuestState.mode === 'full' && shouldShowRepairQuestWallCoverSize(answer)) {
        fields.push('targetWallDetail', 'wallTileShape', 'wallTileFormat', 'wallCoverLengthCm', 'wallCoverWidthCm', 'targetWallLayout');
      }
      if (isRepairQuestBathroomRoom(meta) && answer.targetWall === 'wall_ceramic') {
        fields.push('tileWallCoverage');
        if (answer.tileWallCoverage === 'partial') {
          fields.push('tileWallPartialHeight', 'tileWallUpperFinish');
          if (answer.tileWallUpperFinish === 'wall_mdf_panels') fields.push('tileWallPanelType');
        }
      }
      if (shouldShowRepairQuestPlumbingHatch(meta, answer)) fields.push('plumbingHatch');
      if (repairQuestState.mode === 'full') fields.push('wallDecor');
      if (repairQuestState.mode === 'full') fields.push('wallAccent');
      if (repairQuestState.mode === 'full') fields.push('wallLightSconces', 'wallLightLinear');
      return fields;
    }

    function getRepairQuestDisplayedFinishCeilingFields(answer) {
      if (!shouldShowRepairQuestFinishingBlock(answer)) return [];
      const fields = ['targetCeiling'];
      if (repairQuestState.mode === 'full') {
        fields.push('ceilingLightSpots', 'ceilingLightLines', 'ceilingLightPendants', 'ceilingLightTracks', 'ceilingLightHidden');
        if (!['ceiling_gk', 'ceiling_stretch', 'ceiling_paint'].includes(answer.targetCeiling)) fields.push('targetCeilingDetail');
        if (['ceiling_gk', 'ceiling_stretch'].includes(answer.targetCeiling)) fields.push('ceilingLevels');
        if (answer.targetCeiling === 'ceiling_stretch') {
          fields.push('ceilingStretchType', 'ceilingStretchMaterial');
        }
        if (answer.targetCeiling === 'ceiling_paint') {
          fields.push('ceilingPaintFinish');
        }
        if (answer.targetCeiling === 'ceiling_gk') {
          fields.push('ceilingGkPaint');
          if (answer.ceilingGkPaint !== 'no') fields.push('ceilingGkPaintFinish');
          if (answer.ceilingLevels === 'multilevel') fields.push('ceilingGkShape');
          if (answer.ceilingLightLines === 'yes' || Number(answer.ceilingBacklightLength || 0) > 0) {
            fields.push('ceilingBacklightFullPerimeter', 'ceilingBacklightNicheLength');
          }
          if (Number(answer.trackLights || 0) > 0) fields.push('trackLights', 'ceilingTrackLength');
          if (Number(answer.ceilingCurtainNicheLength || 0) > 0) fields.push('ceilingCurtainNicheLength');
          if (Number(answer.ceilingGkBoxLength || 0) > 0) fields.push('ceilingGkBoxLength', 'ceilingGkBoxHeight');
        }
        if (Number(answer.ledLinesLength || 0) > 0 || ['ceiling_stretch', 'ceiling_stretch_shadow', 'ceiling_stretch_multilevel', 'ceiling_gk', 'ceiling_gk_multilevel'].includes(answer.targetCeiling)) {
          fields.push('ceilingLightLines');
        }
        if (!['ceiling_gk'].includes(answer.targetCeiling) && answer.curtainSolution && answer.curtainSolution !== 'none') fields.push('ceilingCurtainNiche');
        if (!['ceiling_gk'].includes(answer.targetCeiling) && isRepairQuestCeilingWithCutouts(answer)) fields.push('ceilingVentCutouts');
        if (!['ceiling_gk'].includes(answer.targetCeiling) && Number(answer.chandeliers || 0) > 0) fields.push('ceilingRosette');
        if (!['ceiling_gk'].includes(answer.targetCeiling) && shouldShowRepairQuestCeilingHatch(answer)) fields.push('ceilingHatch');
      }
      return fields;
    }

    function shouldShowRepairQuestRoughBlock(answer) {
      return ['rough_target', 'whitebox_target'].includes(answer?.targetResult);
    }

    function shouldShowRepairQuestFinishingBlock(answer) {
      return ['finish_target', 'turnkey_target'].includes(answer?.targetResult);
    }

    function getRepairQuestDisplayedRoughFields(meta, answer) {
      if (!shouldShowRepairQuestRoughBlock(answer)) return [];
      const fields = answer.targetResult === 'rough_target'
        ? ['roughFloorPlan', 'roughWallPlan', 'roughCeilingPlan']
        : ['whiteboxFloorPlan', 'whiteboxWallPlan', 'whiteboxCeilingPlan'];
      if (isRepairQuestScreedFloorPlan(answer)) {
        fields.push('floorScreedMethod', 'floorBaseLayer', 'floorGeotextile', 'floorWaterproofBefore');
        if (answer.floorWaterproofBefore === 'yes') fields.push('floorWaterproofBeforeType');
        fields.push('floorScreedComposition', 'floorWaterproofAfter');
        if (answer.floorWaterproofAfter === 'yes') fields.push('floorWaterproofAfterType');
      }
      if (doesRepairQuestNeedWallPlaster(answer)) {
        fields.push('wallPlasterMethod', 'wallBaseMaterial', 'wallPlasterSystem');
      }
      if (shouldShowRepairQuestWallReinforcement(meta, answer)) {
        fields.push('wallReinforcement');
      }
      return fields;
    }

    function getRepairQuestDisplayedExtraFields(meta, answer) {
      const fields = repairQuestState.mode === 'full'
        ? ['soundproofing']
        : ['soundproofing'];
      if (answer.soundproofing === 'yes') {
        fields.push('floorSoundproofType');
        if (repairQuestState.mode === 'full') fields.push('floorSoundproofPerimeterTape');
      }
      if (repairQuestState.mode === 'full') {
        fields.push('wallSoundproofing');
        if (answer.wallSoundproofing === 'yes') {
          fields.push('wallSoundproofScope', 'wallSoundproofType');
          if (answer.wallSoundproofScope === 'partial') fields.push('wallSoundproofArea');
        }
      }
      if (shouldShowRepairQuestWaterproofing(meta, answer)) {
        if (!shouldShowRepairQuestRoughBlock(answer)) fields.push('floorWaterproofing');
        fields.push('wallWaterproofing', 'ceilingWaterproofing');
      }
      fields.push('surfaceProtection');
      if (answer.surfaceProtection === 'yes') {
        const openings = getRepairQuestOpenings(meta.source);
        if (openings.window > 0) fields.push('protectionWindows');
        if (openings.door > 0) fields.push('protectionDoors');
        fields.push('protectionFloor');
        if (answer.protectionFloor === 'yes') fields.push('protectionFloorArea', 'protectionFloorMaterial');
        fields.push('protectionCommonAreas');
        if (answer.protectionCommonAreas === 'yes') fields.push('protectionCommonArea');
      }
      if (['finish_target', 'turnkey_target'].includes(answer.targetResult)) {
      }
      return fields;
    }

    function getRepairQuestDisplayedJunctionFields(meta, answer) {
      if (!shouldShowRepairQuestFinishingBlock(answer)) return [];
      const fields = ['floorPlinthType', 'ceilingPlinthType'];
      if (shouldShowRepairQuestCurtainSolution(meta)) fields.push('curtainSolution');
      return fields;
    }

    function getRepairQuestDisplayedWarmFloorFields(answer) {
      const fields = ['warmFloor'];
      if (answer?.warmFloor === 'yes') {
        fields.push('warmFloorScope', 'warmFloorType', 'warmFloorInstallMethod', 'warmFloorThermostat', 'warmFloorInsulation');
        if (answer.warmFloorScope === 'partial') fields.push('warmFloorArea');
        if (answer.warmFloorType === 'water') fields.push('warmFloorCollector');
      }
      return fields;
    }

    function getRepairQuestFloorPlanOptions(answer = {}, baseOptions = []) {
      const method = answer.floorScreedMethod || 'mechanized';
      return baseOptions.map(option => {
        if (!['screed', 'screed_warm', 'screed_self_leveling', 'screed_ready', 'self_leveling', 'finish_ready'].includes(option.value)) return option;
        if (method === 'manual') {
          return {
            ...option,
            hint: option.value === 'screed_warm'
              ? 'Теплый пол закладывается внутрь ручной цементно-песчаной стяжки. Подходит для небольших зон и сложного доступа.'
              : 'Ручной способ: актуален для небольших помещений, точечных работ и сложного доступа.'
          };
        }
        return {
          ...option,
          hint: option.value === 'screed_warm'
            ? 'Теплый пол закладывается внутрь механизированной полусухой стяжки. Ниже уточняется тип системы.'
            : option.hint
        };
      });
    }

    function getRepairQuestDisplayedSmartFields(meta, answer) {
      const fields = ['smartHome'];
      if (answer?.smartHome !== 'no') {
        fields.push(...getRepairQuestSmartConfigs(meta, answer.smartHome).map(config => config.field));
        fields.push(
          'smartTempHumiditySensors',
          'smartPresenceSensors',
          'smartDoorSensors',
          'smartIlluminanceSensors',
          'smartGasSensors',
          'smartCoSensors',
          'smartSmokeSensors',
          'smartAirQualitySensors',
          'smartProtocol',
          'smartVoiceAssistant'
        );
      }
      return fields;
    }

    function shouldShowRepairQuestSmartPanelBlock(meta, answer = repairQuestState.answers?.[meta?.key] || {}) {
      if (!meta || !answer || answer.electricalPanelHere !== 'yes') return false;
      const plan = getRepairQuestSmartPanelPlan(meta, answer);
      return Boolean(plan.hasSmart);
    }

    function getRepairQuestDisplayedSmartPanelFields(meta, answer) {
      if (!shouldShowRepairQuestSmartPanelBlock(meta, answer)) return [];
      return [
        'smartPanelSeparateLine',
        'smartPanelUps',
        'smartPanelSurgeProtection',
        'smartPanelDifProtection',
        'smartPanelReservePercent',
        'smartPanelPowerSupplies',
        'smartPanelRelayModules',
        'smartPanelGroupBreakers'
      ];
    }

    function getRepairQuestBlockRequiredFields(answer, blockKey, meta) {
      if (!answer) return [];
      const openings = getRepairQuestOpenings(meta.source);
      const map = {
        state: ['currentState'],
        replanning: ['replanningAction'],
        demolition: ['replanningAction'],
        finishDemolition: [],
        partitionDemolition: [],
        partitionBuild: [],
        result: ['targetResult'],
        roughing: getRepairQuestDisplayedRoughFields(meta, answer),
        openings: [],
        engineering: ['electricalScope'],
        electrical: ['electricalScope'],
        electricalLighting: ['electricalScope'],
        electricalSockets: [],
        electricalFire: [],
        electricalPanel: [],
        smartPanel: getRepairQuestDisplayedSmartPanelFields(meta, answer),
        heating: [],
        climate: [],
        water: [],
        engineeringNode: [],
        drainage: [],
        warmFloor: getRepairQuestDisplayedWarmFloorFields(answer),
        smart: getRepairQuestDisplayedSmartFields(meta, answer),
        equipment: getRepairQuestDisplayedEquipmentFields(meta),
        surfaces: getRepairQuestDisplayedSurfaceFields(meta, answer),
        finishFloor: getRepairQuestDisplayedFinishFloorFields(answer),
        finishWall: getRepairQuestDisplayedFinishWallFields(meta, answer),
        finishCeiling: getRepairQuestDisplayedFinishCeilingFields(answer),
        finishOpenings: [],
        finishJunctions: getRepairQuestDisplayedJunctionFields(meta, answer),
        finishStairs: ['stairsScope'],
        extras: getRepairQuestDisplayedExtraFields(meta, answer)
      };

      if (answer.currentState === 'old_finish') {
        map.finishDemolition.push('oldFinishScope');
      }
      if (answer.currentState === 'old_finish' && answer.oldFinishScope !== 'none') {
        map.finishDemolition.push('demoFloorScope', 'demoWallScope', 'demoCeilingScope');
        if (answer.demoFloorScope !== 'none') map.finishDemolition.push('currentFloor');
        if (answer.demoFloorScope === 'partial') map.finishDemolition.push('demoFloorArea');
        if (answer.demoWallScope !== 'none') map.finishDemolition.push('currentWall');
        if (answer.demoWallScope === 'partial' && !Number(answer.demoWallArea || 0) && !Number(answer.demoWallLength || 0)) {
          map.finishDemolition.push('demoWallArea');
        }
        if (answer.demoCeilingScope !== 'none') map.finishDemolition.push('currentCeiling');
        if (answer.demoCeilingScope === 'partial') map.finishDemolition.push('demoCeilingArea');
      }
      if (shouldShowRepairQuestPartitionDemolition(meta, answer)) {
        map.partitionDemolition.push('partitionDemoMaterial');
        if (!Number(answer.partitionDemoArea || 0) && !Number(answer.partitionDemoLength || 0)) {
          map.partitionDemolition.push('partitionDemoLength');
        }
      }
      if (shouldShowRepairQuestPartitionBuild(meta, answer)) {
        map.partitionBuild.push('partitionBuildMaterial');
        if (!Number(answer.partitionBuildArea || 0) && !Number(answer.partitionBuildLength || 0)) {
          map.partitionBuild.push('partitionBuildLength');
        }
      }
      if (repairQuestState.mode === 'full') {
        if (hasRepairQuestOpenings(meta)) map.openings.push('openingPlans');
      } else {
        if (openings.door > 0) map.openings.push('doorsAction');
        if (openings.window > 0) map.openings.push('windowsAction');
        if (openings.balcony > 0 || canRepairQuestHaveBalconyOpening(meta)) map.openings.push('balconyAction');
        if (map.openings.length && shouldRequireRepairQuestOpeningDetails(answer)) {
          map.openings.push('openingDetails');
        }
      }
      map.finishOpenings = [...map.openings];

      if (isRepairQuestPlumbingRoom(meta)) map.engineering.push('plumbingScope');
      if (isRepairQuestPlumbingRoom(meta) && answer.plumbingScope !== 'no_touch') map.engineering.push('waterFilter');
      if (isRepairQuestHeatingRoom(meta)) map.engineering.push('heatingScope');
      if (isRepairQuestClimateRoom(meta)) map.engineering.push('climateScope');
      if (isRepairQuestClimateRoom(meta)) map.engineering.push('ventilationSystem');
      if (isRepairQuestClimateRoom(meta) && answer.climateScope !== 'not_needed') {
        map.engineering.push('acSystemType');
      }
      if (shouldRepairQuestCountLighting(answer) && answer.bedsideLight === 'yes') {
        map.electricalLighting.push('bedsideLightCount');
      }
      if (repairQuestState.mode === 'full' && answer.electricalScope !== 'no_touch') {
        if (answer.electricalScope === 'add_move_points') map.electricalLighting.push('electricalWorkScope');
        if (shouldRepairQuestCountWallElectrical(answer)) {
          map.engineering.push('singleSockets', 'doubleSockets', 'tripleSockets', 'singleSwitches', 'doubleSwitches', 'tripleSwitches', 'internetPoints', 'tvPoints');
          map.electricalSockets.push(
            'singleSockets',
            'doubleSockets',
            'tripleSockets',
            'childProtectedSingleSockets',
            'childProtectedDoubleSockets',
            'childProtectedTripleSockets',
            'singleSwitches',
            'doubleSwitches',
            'tripleSwitches',
            'masterLightSwitches',
            'masterPowerSwitches',
            'generalMasterSwitch',
            'internetSocket',
            'tvSocket',
            'internetPoints',
            'tvPoints'
          );
        }
        if (shouldRepairQuestCountLighting(answer)) {
          map.electricalLighting.push('spotLights', 'chandeliers', 'wallLights', 'floorLights', 'trackLights', 'nightLightPoints', 'motionLightSensors', 'motionLightTarget', 'ledLinesLength', 'wallLinearLightLength', 'ceilingBacklightLength', 'plinthBacklightLength', 'ceilingTrackLength');
        }
        map.electricalFire.push('fireProtection');
        if (answer.fireProtection === 'yes') {
          map.electricalFire.push('fireProtectionType', 'fireSmokeDetectors', 'fireCoDetectors');
        }
        if (shouldRepairQuestCountWallElectrical(answer) && isRepairQuestMoistureSocketRoom(meta)) {
          map.engineering.push('moistureProofSockets');
          map.electricalSockets.push('moistureProofSockets');
        }
      }
      if (repairQuestState.mode === 'full' && shouldShowRepairQuestElectricalPanel(meta, answer)) {
        map.electricalPanel.push('electricalPanelHere');
        if (answer.electricalPanelHere === 'yes') {
          map.electricalPanel.push(
            'electricalPanelMountType',
            'electricalPanelBodyMaterial',
            'electricalPanelProtectionDegree',
            'electricalPanelDinRail',
            'electricalPanelNeutralBus',
            'electricalPanelGroundBus',
            'electricalPanelIntroBreaker',
            'electricalPanelSelectiveRcd',
            'electricalPanelRcd',
            'electricalPanelWetRcd',
            'electricalPanelDifBreakers',
            'electricalPanelBreakers',
            'electricalPanelMeter',
            'electricalPanelSurgeProtection',
            'electricalPanelVoltageRelay',
            'electricalPanelReservePercent',
            'electricalPanelObjectType',
            'electricalPanelVoltageStability',
            'electricalPanelRcdType',
            'electricalPanelBreakerCurve'
          );
        }
      }
      if (answer.electricalScope !== 'no_touch') {
        getRepairQuestDisplayedElectricalScenarioFields(meta, answer).forEach(field => {
          map[isRepairQuestWallElectricalScenarioField(field) ? 'electricalSockets' : 'electricalLighting'].push(field);
        });
      }
      if (repairQuestState.mode === 'full' && isRepairQuestPlumbingRoom(meta) && answer.plumbingScope !== 'no_touch') {
        map.engineering.push('waterPoints', 'drainagePoints');
      }
      if (repairQuestState.mode === 'full' && isRepairQuestHeatingRoom(meta) && answer.heatingScope !== 'no_touch') {
        map.engineering.push('heatingDevices', 'heatingSystemType');
      }
      if (isRepairQuestHeatingRoom(meta)) map.heating.push('heatingScope');
      if (repairQuestState.mode === 'full' && isRepairQuestHeatingRoom(meta) && answer.heatingScope !== 'no_touch') {
        map.heating.push('heatingDevices', 'heatingSystemType');
      }
      if (isRepairQuestClimateRoom(meta)) map.climate.push('climateScope', 'ventilationSystem');
      if (isRepairQuestClimateRoom(meta) && answer.climateScope !== 'not_needed') {
        map.climate.push('acSystemType');
      }
      if (repairQuestState.mode === 'full' && isRepairQuestClimateRoom(meta) && answer.climateScope !== 'not_needed') {
        map.climate.push('acUnits', 'acRouteType', 'acDrainageType');
      }
      if (repairQuestState.mode === 'full' && isRepairQuestClimateRoom(meta) && ['exhaust_fan', 'hrv', 'supply_unit', 'ducted_supply_exhaust'].includes(answer.ventilationSystem)) {
        map.climate.push('ventilationControl');
      }
      if (repairQuestState.mode === 'full' && isRepairQuestClimateRoom(meta) && ['exhaust_fan', 'hrv', 'supply_unit', 'ducted_supply_exhaust'].includes(answer.ventilationSystem)) {
        map.climate.push('ventPoints');
      }
      if (repairQuestState.mode === 'full' && isRepairQuestClimateRoom(meta) && ['supply_unit', 'ducted_supply_exhaust'].includes(answer.ventilationSystem)) {
        map.climate.push('ventilationDuctLength');
      }
      if (isRepairQuestPlumbingRoom(meta)) map.water.push('plumbingScope');
      if (isRepairQuestPlumbingRoom(meta) && answer.plumbingScope !== 'no_touch') {
        map.water.push('waterFilter');
        if (repairQuestState.mode === 'full') map.water.push('waterPoints');
      }
      if (isRepairQuestWetRoom(meta)) map.water.push('leakProtection');
      if (repairQuestState.mode === 'full' && isRepairQuestEngineeringNodeRoom(meta)) {
        map.engineeringNode.push('waterCollectorHere', 'heatingDistributionHere');
        if (answer.waterCollectorHere === 'yes') {
          map.engineeringNode.push(
            'waterCollectorType',
            'waterCollectorColdOutlets',
            'waterCollectorHotOutlets',
            'waterCollectorInstall',
            'waterCollectorFilters',
            'waterMeters',
            'waterPressureReducers',
            'waterCheckValves',
            'waterPipeMaterial',
            'waterPipeLayout',
            'waterPipeLength'
          );
        }
        if (answer.heatingDistributionHere === 'yes') {
          map.engineeringNode.push('heatingDistributionType', 'heatingPipeMaterial', 'heatingPipeLayout', 'heatingPipeLength');
        }
      }
      if (isRepairQuestPlumbingRoom(meta) && answer.plumbingScope !== 'no_touch' && repairQuestState.mode === 'full') {
        map.drainage.push('drainagePoints');
      }
      if (!isRepairQuestKitchenRoom(meta)) {
        map.surfaces = map.surfaces.filter(field => field !== 'backsplash');
      }
      if (!isRepairQuestBathroomRoom(meta) || answer.targetWall !== 'wall_ceramic') {
        map.surfaces = map.surfaces.filter(field => !['tileZones', 'tileWallCoverage', 'tileWallPartialHeight', 'tileWallUpperFinish', 'tileWallPanelType'].includes(field));
        map.finishWall = map.finishWall.filter(field => !['tileZones', 'tileWallCoverage', 'tileWallPartialHeight', 'tileWallUpperFinish', 'tileWallPanelType'].includes(field));
      }
      if (isRepairQuestKitchenRoom(meta) && (answer.backsplash || 'none') !== 'none') {
        map.surfaces.push('backsplashHeight', 'backsplashMaterial', 'backsplashEdge');
        map.finishWall.push('backsplashHeight', 'backsplashMaterial', 'backsplashEdge');
      }
      if (shouldShowRepairQuestPlumbingHatch(meta, answer)) {
        map.finishWall.push('plumbingHatch');
      }
      if (repairQuestState.mode === 'full' && shouldShowRepairQuestCeilingHatch(answer)) {
        map.surfaces.push('ceilingHatch');
      }

      if (blockKey === 'demolition' && !shouldShowRepairQuestDemolition(meta, answer)) return [];
      if (blockKey === 'finishDemolition' && !shouldShowRepairQuestFinishDemolition(answer)) return [];
      if (blockKey === 'partitionDemolition' && !shouldShowRepairQuestPartitionDemolition(meta, answer)) return [];
      if (blockKey === 'partitionBuild' && !shouldShowRepairQuestPartitionBuild(meta, answer)) return [];
      if (blockKey === 'roughing' && !shouldShowRepairQuestRoughBlock(answer)) return [];
      if (blockKey === 'warmFloor' && repairQuestState.mode !== 'full' && answer.roughFloorPlan !== 'screed_warm') return [];
      if (blockKey === 'engineeringNode' && (repairQuestState.mode !== 'full' || !isRepairQuestEngineeringNodeRoom(meta))) return [];
      if (blockKey === 'openings' && !hasRepairQuestOpenings(meta)) return [];
      if (blockKey === 'surfaces' && !shouldShowRepairQuestFinishingBlock(answer)) return [];
      if (blockKey === 'finishOpenings' && !hasRepairQuestOpenings(meta)) return [];
      if (['finishFloor', 'finishWall', 'finishCeiling', 'finishJunctions', 'finishStairs'].includes(blockKey) && !shouldShowRepairQuestFinishingBlock(answer)) return [];
      return map[blockKey] || [];
    }

    function isRepairQuestBlockReady(roomKey, blockKey) {
      const answer = repairQuestState.answers[roomKey];
      if (!answer) return false;
      return getRepairQuestBlockRequiredFields(answer, blockKey, repairQuestState.rooms.find(room => room.key === roomKey))
        .every(field => hasRepairQuestAnswerValue(answer[field]));
    }

    function getQuestOptionLabel(options, value) {
      return options.find(option => option.value === value)?.label || '';
    }

    function getRepairQuestBlockSummary(roomKey, blockKey) {
      const answer = repairQuestState.answers[roomKey];
      const meta = repairQuestState.rooms.find(room => room.key === roomKey);
      if (!answer || !meta) return '';

      if (blockKey === 'state') {
        return repairQuestCurrentStateLabels[answer.currentState] || '';
      }

      if (blockKey === 'replanning') {
        return getQuestOptionLabel(repairQuestState.mode === 'full' ? repairQuestReplanningFullOptions : repairQuestReplanningApproxOptions, answer.replanningAction);
      }

      if (blockKey === 'finishDemolition') {
        const floorCount = Array.isArray(answer.currentFloor) ? answer.currentFloor.length : 0;
        const wallCount = Array.isArray(answer.currentWall) ? answer.currentWall.length : 0;
        const ceilingCount = Array.isArray(answer.currentCeiling) ? answer.currentCeiling.length : 0;
        const demoAreas = getRepairQuestDemolitionScopeAreas(meta, answer);
        if (answer.oldFinishScope === 'none') return 'демонтаж старой отделки не нужен';
        return [
          answer.demoFloorScope !== 'none' ? `пол ${floorCount} сл., ${demoAreas.floor} м²` : '',
          answer.demoWallScope !== 'none' ? `стены ${wallCount} сл., ${demoAreas.wall} м²` : '',
          answer.demoCeilingScope !== 'none' ? `потолок ${ceilingCount} сл., ${demoAreas.ceiling} м²` : ''
        ].filter(Boolean).join(' • ');
      }

      if (blockKey === 'partitionDemolition') {
        const partitionDemoArea = getRepairQuestWallAreaFromAnswer(answer, meta, 'partitionDemoArea', 'partitionDemoLength');
        return partitionDemoArea > 0
          ? `${getRepairQuestPartitionMaterialLabel(answer.partitionDemoMaterial)}, ${partitionDemoArea.toFixed(2)} м²`
          : getRepairQuestPartitionMaterialLabel(answer.partitionDemoMaterial);
      }

      if (blockKey === 'partitionBuild') {
        const partitionBuildArea = getRepairQuestWallAreaFromAnswer(answer, meta, 'partitionBuildArea', 'partitionBuildLength');
        return partitionBuildArea > 0
          ? `${getRepairQuestPartitionMaterialLabel(answer.partitionBuildMaterial)}, ${partitionBuildArea.toFixed(2)} м²`
          : getRepairQuestPartitionMaterialLabel(answer.partitionBuildMaterial);
      }

      if (blockKey === 'demolition') {
        return getQuestOptionLabel(repairQuestState.mode === 'full' ? repairQuestReplanningFullOptions : repairQuestReplanningApproxOptions, answer.replanningAction);
      }

      if (blockKey === 'result') {
        return getQuestOptionLabel(repairQuestTargetResultOptions, answer.targetResult);
      }

      if (blockKey === 'roughing') {
        if (answer.targetResult === 'rough_target') {
          return [
            getQuestOptionLabel(repairQuestRoughFloorOptions, answer.roughFloorPlan),
            getQuestOptionLabel(repairQuestRoughWallOptions, answer.roughWallPlan),
            getQuestOptionLabel(repairQuestWallPlasterMethodOptions, answer.wallPlasterMethod),
            getRepairQuestWallPlasterSystemLabel(getRepairQuestEffectiveWallPlasterSystem(meta, answer)),
            getQuestOptionLabel(repairQuestRoughCeilingOptions, answer.roughCeilingPlan),
            answer.wallReinforcement === 'mesh' ? 'Армирование сеткой' : answer.wallReinforcement === 'additive' ? 'Армирующая добавка' : ''
          ].filter(Boolean).join(' • ');
        }
        if (answer.targetResult === 'whitebox_target') {
          return [
            getQuestOptionLabel(repairQuestWhiteboxFloorOptions, answer.whiteboxFloorPlan),
            getQuestOptionLabel(repairQuestWhiteboxWallOptions, answer.whiteboxWallPlan),
            getQuestOptionLabel(repairQuestWallPlasterMethodOptions, answer.wallPlasterMethod),
            getRepairQuestWallPlasterSystemLabel(getRepairQuestEffectiveWallPlasterSystem(meta, answer)),
            getQuestOptionLabel(repairQuestWhiteboxCeilingOptions, answer.whiteboxCeilingPlan),
            answer.wallReinforcement === 'mesh' ? 'Армирование сеткой' : answer.wallReinforcement === 'additive' ? 'Армирующая добавка' : ''
          ].filter(Boolean).join(' • ');
        }
        return '';
      }

      if (blockKey === 'openings') {
        if (repairQuestState.mode === 'full') {
          syncRepairQuestOpeningPlans(meta, answer);
          const planCounts = ['door', 'window', 'balcony'].map(openingType => {
            const label = openingType === 'door' ? 'двери' : openingType === 'window' ? 'окна' : 'балкон';
            const count = (answer.openingPlans?.[openingType] || []).filter((_, index) => hasRepairQuestOpeningPlanWork(answer, openingType, index)).length;
            return count ? `${label}: ${count}` : '';
          }).filter(Boolean);
          return planCounts.length ? planCounts.join(' • ') : 'проемы не трогаем';
        }
        const parts = [];
        if (answer.doorsAction) parts.push(`Двери: ${getQuestOptionLabel(repairQuestState.mode === 'full' ? repairQuestDoorActionFullOptions : repairQuestDoorActionApproxOptions, answer.doorsAction)}`);
        if (answer.windowsAction) parts.push(`Окна: ${getQuestOptionLabel(repairQuestState.mode === 'full' ? repairQuestWindowActionFullOptions : repairQuestWindowActionApproxOptions, answer.windowsAction)}`);
        if (answer.balconyAction) parts.push(`Балкон: ${getQuestOptionLabel(getRepairQuestBalconyActionOptions(meta), answer.balconyAction)}`);
        return parts.join(' • ');
      }

      if (blockKey === 'finishOpenings') {
        return getRepairQuestBlockSummary(roomKey, 'openings');
      }

      if (blockKey === 'finishJunctions') {
        return [
          getQuestOptionLabel(repairQuestPlinthOptions, answer.floorPlinthType),
          getQuestOptionLabel(repairQuestCeilingPlinthOptions, answer.ceilingPlinthType),
          shouldShowRepairQuestCurtainSolution(meta) ? getQuestOptionLabel(repairQuestCurtainOptions, answer.curtainSolution) : ''
        ].filter(Boolean).join(' • ');
      }

      if (blockKey === 'engineering' || blockKey === 'electrical') {
        const parts = [
          getQuestOptionLabel(repairQuestElectricalScopeOptions, answer.electricalScope),
          answer.internetSocket === 'yes' ? `интернет-розетки ${answer.internetPoints || 0}` : '',
          answer.tvSocket === 'yes' ? `ТВ-розетки ${answer.tvPoints || 0}` : '',
          answer.fireProtection === 'yes' ? 'пожарные датчики' : ''
        ].filter(Boolean);
        if (repairQuestState.mode === 'full') {
          parts.push(`розетки ${getRepairQuestTotalSockets(answer) || 0}`);
          parts.push(`выкл. ${getRepairQuestSwitchesTotal(answer) || 0}`);
          if (Number(answer.masterLightSwitches || 0) || Number(answer.masterPowerSwitches || 0)) {
            parts.push(`мастер ${Number(answer.masterLightSwitches || 0) + Number(answer.masterPowerSwitches || 0)}`);
          }
          parts.push(`свет ${getRepairQuestLightingTotal(answer) || 0}`);
          const ledLength = getRepairQuestLedLightingLength(answer);
          if (ledLength > 0) parts.push(`LED ${Number(ledLength.toFixed(2))} м`);
        }
        return parts.join(' • ');
      }

      if (blockKey === 'electricalLighting') {
        const ledLength = getRepairQuestLedLightingLength(answer);
        return [
          getQuestOptionLabel(repairQuestElectricalScopeOptions, answer.electricalScope),
          repairQuestState.mode === 'full' && answer.electricalScope !== 'no_touch' ? `свет ${getRepairQuestLightingTotal(answer) || 0}` : '',
          ledLength > 0 ? `LED ${Number(ledLength.toFixed(2))} м` : ''
        ].filter(Boolean).join(' • ');
      }

      if (blockKey === 'electricalSockets') {
        return answer.electricalScope === 'no_touch'
          ? 'не трогаем'
          : [
            `розетки ${getRepairQuestTotalSockets(answer) || 0}`,
            `выкл. ${getRepairQuestSwitchesTotal(answer) || 0}`,
            answer.internetSocket === 'yes' ? `интернет ${answer.internetPoints || 0}` : '',
            answer.tvSocket === 'yes' ? `ТВ ${answer.tvPoints || 0}` : ''
          ].filter(Boolean).join(' • ');
      }

      if (blockKey === 'electricalFire') {
        return answer.fireProtection === 'yes'
          ? [
            `${answer.fireSmokeDetectors || 0} дым.`,
            Number(answer.fireCoDetectors || 0) > 0 ? `${answer.fireCoDetectors} CO` : '',
            answer.fireProtectionType === 'addressable' ? 'адресная' : answer.fireProtectionType === 'wired' ? 'проводная' : 'автономная'
          ].filter(Boolean).join(' • ')
          : 'не нужны';
      }

      if (blockKey === 'electricalPanel') {
        return answer.electricalPanelHere === 'yes'
          ? [
            `${answer.electricalPanelModules || 0} мод.`,
            `${answer.electricalPanelBreakers || 0} авт.`,
            `${Number(answer.electricalPanelLoadKw || 0).toLocaleString('ru-RU', { maximumFractionDigits: 1 })} кВт`,
            answer.electricalPanelCalcConfirmed === 'yes' ? 'расчет подтвержден' : ''
          ].filter(Boolean).join(' • ')
          : 'щит не в этой комнате';
      }

      if (blockKey === 'warmFloor') {
        if (answer.warmFloor !== 'yes') return 'не нужен';
        const area = getRepairQuestWarmFloorArea(meta, answer);
        const typeLabel = getQuestOptionLabel(repairQuestWarmFloorTypeOptions, answer.warmFloorType);
        const scope = answer.warmFloorScope === 'partial' ? 'частично' : 'вся площадь';
        return [typeLabel, scope, area ? `${area} м²` : ''].filter(Boolean).join(' • ');
      }

      if (blockKey === 'heating') {
        return [
          getQuestOptionLabel(repairQuestHeatingScopeOptions, answer.heatingScope),
          repairQuestState.mode === 'full' && answer.heatingScope !== 'no_touch' ? `${answer.heatingDevices || 0} прибор.` : '',
          repairQuestState.mode === 'full' && answer.heatingScope !== 'no_touch' ? getQuestOptionLabel(repairQuestHeatingTypeOptions, answer.heatingSystemType) : ''
        ].filter(Boolean).join(' • ');
      }

      if (blockKey === 'climate') {
        return [
          getQuestOptionLabel(repairQuestClimateScopeOptions, answer.climateScope),
          answer.climateScope !== 'not_needed' ? getQuestOptionLabel(repairQuestAcSystemOptions, answer.acSystemType) : '',
          getQuestOptionLabel(repairQuestVentilationSystemOptions, answer.ventilationSystem),
          repairQuestState.mode === 'full' && answer.climateScope !== 'not_needed' ? `${normalizeRepairQuestAcUnits(answer.acUnits)} внутр. блок.` : '',
          repairQuestState.mode === 'full' && ['supply_unit', 'ducted_supply_exhaust'].includes(answer.ventilationSystem) ? `${answer.ventilationDuctLength || 0} м воздуховодов` : ''
        ].filter(Boolean).join(' • ');
      }

      if (blockKey === 'water') {
        return [
          getQuestOptionLabel(repairQuestPlumbingScopeOptions, answer.plumbingScope),
          repairQuestState.mode === 'full' && answer.plumbingScope !== 'no_touch' ? `${answer.waterPoints || 0} водоточек` : '',
          answer.waterFilter === 'yes' ? 'очистка воды' : '',
          answer.leakProtection === 'yes' ? 'защита от протечек' : ''
        ].filter(Boolean).join(' • ');
      }

      if (blockKey === 'drainage') {
        return repairQuestState.mode === 'full' && answer.plumbingScope !== 'no_touch'
          ? `${answer.drainagePoints || 0} канализационных точек`
          : getQuestOptionLabel(repairQuestPlumbingScopeOptions, answer.plumbingScope);
      }

      if (blockKey === 'smart') {
        const parts = [getQuestOptionLabel(repairQuestSmartHomeOptions, answer.smartHome)];
        const configMap = Object.fromEntries(getRepairQuestSmartConfigs(meta, answer.smartHome).map(config => [config.field, config.label]));
        getRepairQuestSmartConfigs(meta, answer.smartHome)
          .filter(config => answer[config.field] === 'yes')
          .slice(0, 3)
          .forEach(config => parts.push(configMap[config.field] || config.field));
        return parts.filter(Boolean).join(' • ');
      }

      if (blockKey === 'equipment') {
        const configMap = Object.fromEntries(getRepairQuestEquipmentConfigs(meta).map(config => [config.field, config.label]));
        return getRepairQuestDisplayedEquipmentFields(meta)
          .filter(field => {
            const value = answer[field];
            return value === 'yes' || (typeof value === 'string' && value !== 'no' && value !== 'none' && value !== 'standard') || (typeof value === 'number' && value > 0);
          })
          .slice(0, 3)
          .map(field => field === 'bedsideLightCount' ? `${answer.bedsideLightCount || 0} прикроватн. свет.` : (configMap[field] || field))
          .join(' • ');
      }

      if (blockKey === 'surfaces') {
        return [
          getRepairFinishingOption('floor', answer.targetFloor)?.label,
          getRepairFinishingOption('wall', answer.targetWall)?.label,
          getRepairFinishingOption('ceiling', answer.targetCeiling)?.label,
          answer.ceilingHatch === 'yes' ? 'Сервисный люк в потолке' : ''
        ].filter(Boolean).join(' • ');
      }

      if (blockKey === 'finishFloor') {
        return [
          getRepairFinishingOption('floor', answer.targetFloor)?.label,
          getRepairQuestFloorDetailOptions(answer.targetFloor).find(option => option.value === answer.targetFloorDetail)?.label,
          isRepairQuestFloorTileTarget(answer) ? getRepairQuestFloorLayoutLabel(answer) : '',
          shouldShowRepairQuestFloorCoverSize(answer) ? `${Number(answer.floorCoverLengthMm || 0).toLocaleString('ru-RU')}x${Number(answer.floorCoverWidthMm || 0).toLocaleString('ru-RU')} см` : '',
          answer.targetFloorBorderEnabled === 'yes' ? 'бордюр' : '',
          answer.targetFloorDecorEnabled === 'yes' ? `${answer.targetFloorDecorCount || 0} декор. эл.` : ''
        ].filter(Boolean).join(' • ');
      }

      if (blockKey === 'finishWall') {
        return [
          getRepairFinishingOption('wall', answer.targetWall)?.label,
          isRepairQuestKitchenRoom(meta) ? getQuestOptionLabel([
            { value: 'full', label: 'полный фартук' },
            { value: 'accent', label: 'акцентный фартук' },
            { value: 'none', label: 'без фартука' }
          ], answer.backsplash) : '',
          isRepairQuestKitchenRoom(meta) && (answer.backsplash || 'none') !== 'none' ? getQuestOptionLabel(repairQuestBacksplashMaterialOptions, answer.backsplashMaterial) : '',
          isRepairQuestBathroomRoom(meta) && answer.targetWall === 'wall_ceramic'
            ? (answer.tileWallCoverage === 'partial' ? `плитка до ${answer.tileWallPartialHeight || 0} м` : 'плитка до потолка')
            : '',
          isRepairQuestBathroomRoom(meta) && answer.targetWall === 'wall_ceramic' && answer.tileWallCoverage === 'partial'
            ? `выше: ${getRepairQuestUpperWallFinishLabel(answer)}`
            : '',
          answer.plumbingHatch === 'yes' ? 'сантехнический люк' : ''
        ].filter(Boolean).join(' • ');
      }

      if (blockKey === 'finishCeiling') {
        return [
          getRepairFinishingOption('ceiling', answer.targetCeiling)?.label,
          answer.targetCeiling === 'ceiling_stretch'
            ? `${answer.ceilingStretchType === 'shadow' ? 'теневой / парящий' : 'стандартный'} • ${answer.ceilingStretchMaterial === 'pvc' ? 'ПВХ/пленка' : 'тканевый'}`
            : answer.targetCeiling === 'ceiling_paint'
              ? getQuestOptionLabel(repairQuestCeilingPaintFinishOptions, answer.ceilingPaintFinish)
              : answer.targetCeiling === 'ceiling_gk' && answer.ceilingGkPaint !== 'no'
                ? `покраска: ${getQuestOptionLabel(repairQuestCeilingPaintFinishOptions, answer.ceilingGkPaintFinish)}`
                : getRepairQuestCeilingDetailOptions(answer.targetCeiling).find(option => option.value === answer.targetCeilingDetail)?.label,
          answer.ceilingLevels === 'multilevel' ? '2+ уровня' : '',
          answer.ceilingLevels === 'multilevel' && answer.ceilingGkShape === 'curved' ? 'Расчет по дизайн проекту' : '',
          answer.ceilingLightLines === 'yes' ? 'световые линии' : '',
          Number(answer.ceilingBacklightNicheLength || 0) > 0 ? `ниша ${Number(answer.ceilingBacklightNicheLength || 0).toLocaleString('ru-RU', { maximumFractionDigits: 2 })} м` : '',
          Number(answer.trackLights || 0) > 0 ? `трек ${answer.trackLights} шт.` : '',
          getRepairQuestCeilingLightCutoutQty(answer) > 0 ? `${getRepairQuestCeilingLightCutoutQty(answer)} вырезов под свет` : '',
          answer.ceilingHatch === 'yes' ? 'сервисный люк' : ''
        ].filter(Boolean).join(' • ');
      }

      if (blockKey === 'finishStairs') {
        return answer.stairsScope === 'yes' ? 'нужны лестницы/перила' : 'не нужны';
      }

      if (blockKey === 'extras') {
        return [
          answer.warmFloor === 'yes' ? 'Теплый пол' : '',
          isRepairQuestFloorWaterproofingEnabled(answer) ? 'Гидроизоляция пола' : '',
          isRepairQuestWallWaterproofingEnabled(answer) ? 'Гидроизоляция стен' : '',
          isRepairQuestCeilingWaterproofingEnabled(answer) ? 'Гидроизоляция потолка' : '',
          answer.soundproofing === 'yes' ? `Пол: ${getQuestOptionLabel(repairQuestFloorSoundproofOptions, answer.floorSoundproofType)}` : '',
          answer.wallSoundproofing === 'yes' ? `Стены: ${getQuestOptionLabel(repairQuestWallSoundproofOptions, answer.wallSoundproofType)} ${getRepairQuestWallSoundproofArea(meta, answer)} м²` : '',
          answer.surfaceProtection === 'yes' ? 'Укрытие поверхностей' : ''
        ].filter(Boolean).join(' • ');
      }

      return '';
    }

    function getRepairQuestSceneState() {
      const scene = {
        targetWall: 'wall_paint',
        targetFloor: 'floor_engineered',
        targetCeiling: 'ceiling_stretch_shadow',
        lightingScenario: 'basic',
        tileZones: 'none',
        wallAccent: 'none',
        plinthType: 'standard',
        floorPlinthType: 'standard',
        ceilingPlinthType: 'none',
        smartHome: 'no',
        securityLevel: 'none',
        curtainSolution: 'none',
        changeWindow: 'no',
        changeDoor: 'no',
        warmFloor: 'no',
        internetSocket: 'no',
        tvSocket: 'no',
        stateConfirmed: false,
        demolitionConfirmed: false,
        roughingConfirmed: false,
        surfacesConfirmed: false,
        engineeringConfirmed: false,
        smartConfirmed: false,
        extrasConfirmed: false
      };

      repairQuestState.rooms.forEach(room => {
        const answer = repairQuestState.answers[room.key];
        if (!answer) return;
        if (isRepairQuestBlockConfirmed(room.key, 'state')) scene.stateConfirmed = true;
        if (isRepairQuestBlockConfirmed(room.key, 'demolition')) scene.demolitionConfirmed = true;
        if (isRepairQuestBlockConfirmed(room.key, 'roughing')) scene.roughingConfirmed = true;
        if (isRepairQuestBlockConfirmed(room.key, 'surfaces') || isRepairQuestBlockConfirmed(room.key, 'finishFloor') || isRepairQuestBlockConfirmed(room.key, 'finishWall') || isRepairQuestBlockConfirmed(room.key, 'finishCeiling')) {
          scene.surfacesConfirmed = true;
          scene.targetWall = answer.targetWall || scene.targetWall;
          scene.targetFloor = answer.targetFloor || scene.targetFloor;
          scene.targetCeiling = answer.targetCeiling || scene.targetCeiling;
        }
        if (isRepairQuestBlockConfirmed(room.key, 'engineering') || isRepairQuestBlockConfirmed(room.key, 'electrical') || isRepairQuestBlockConfirmed(room.key, 'electricalLighting') || isRepairQuestBlockConfirmed(room.key, 'electricalSockets') || isRepairQuestBlockConfirmed(room.key, 'electricalFire') || isRepairQuestBlockConfirmed(room.key, 'electricalPanel') || isRepairQuestBlockConfirmed(room.key, 'water') || isRepairQuestBlockConfirmed(room.key, 'drainage') || isRepairQuestBlockConfirmed(room.key, 'heating') || isRepairQuestBlockConfirmed(room.key, 'climate')) {
          scene.engineeringConfirmed = true;
          scene.securityLevel = answer.securityLevel || scene.securityLevel;
          scene.internetTv = answer.internetSocket === 'yes' || answer.tvSocket === 'yes' ? 'yes' : scene.internetTv;
        }
        if (isRepairQuestBlockConfirmed(room.key, 'smart')) {
          scene.smartConfirmed = true;
          scene.smartHome = answer.smartHome || scene.smartHome;
        }
        if (isRepairQuestBlockConfirmed(room.key, 'extras') || isRepairQuestBlockConfirmed(room.key, 'finishJunctions')) {
          scene.extrasConfirmed = true;
          scene.lightingScenario = answer.lightingScenario || scene.lightingScenario;
          scene.tileZones = answer.tileZones || scene.tileZones;
          scene.wallAccent = Array.isArray(answer.wallAccent)
            ? (answer.wallAccent.find(value => value !== 'none') || 'none')
            : (answer.wallAccent || scene.wallAccent);
          scene.plinthType = answer.plinthType || scene.plinthType;
          scene.floorPlinthType = answer.floorPlinthType || scene.floorPlinthType;
          scene.ceilingPlinthType = answer.ceilingPlinthType || scene.ceilingPlinthType;
          scene.curtainSolution = answer.curtainSolution || scene.curtainSolution;
          scene.changeWindow = answer.changeWindow || scene.changeWindow;
          scene.changeDoor = answer.changeDoor || scene.changeDoor;
          scene.warmFloor = answer.warmFloor || scene.warmFloor;
        }
      });

      return scene;
    }

    function getRepairQuestBlockVisual(blockKey) {
      const map = {
        state: { icon: 'fa-clipboard-check', label: 'Исходное состояние' },
        replanning: { icon: 'fa-compass-drafting', label: 'Перепланировка' },
        finishDemolition: { icon: 'fa-hammer', label: 'Демонтаж отделки' },
        partitionDemolition: { icon: 'fa-person-digging', label: 'Демонтаж перегородок' },
        partitionBuild: { icon: 'fa-border-all', label: 'Перегородки' },
        result: { icon: 'fa-bullseye', label: 'Что нужно получить' },
        finishFloor: { icon: 'fa-ruler-horizontal', label: 'Чистовая отделка: Пол' },
        finishWall: { icon: 'fa-table-cells-large', label: 'Чистовая отделка: Стены' },
        finishCeiling: { icon: 'fa-layer-group', label: 'Чистовая отделка: Потолок' },
        finishOpenings: { icon: 'fa-door-open', label: 'Чистовая отделка: Проемы' },
        finishJunctions: { icon: 'fa-ruler-combined', label: 'Финишные примыкания' },
        equipment: { icon: 'fa-kitchen-set', label: 'Оснащение помещения' },
        finishStairs: { icon: 'fa-stairs', label: 'Лестницы и перила' },
        roughing: { icon: 'fa-trowel-bricks', label: 'Черновая отделка' },
        warmFloor: { icon: 'fa-temperature-half', label: 'Теплый пол' },
        electrical: { icon: 'fa-bolt', label: 'Электрика' },
        electricalLighting: { icon: 'fa-lightbulb', label: 'Организация света' },
        electricalSockets: { icon: 'fa-plug-circle-bolt', label: 'Розетки и управление' },
        electricalFire: { icon: 'fa-fire-extinguisher', label: 'Противопожарные датчики' },
        electricalPanel: { icon: 'fa-table-columns', label: 'Распределительный щит' },
        smartPanel: { icon: 'fa-microchip', label: 'Распределительный щит умного дома' },
        heating: { icon: 'fa-fire-flame-simple', label: 'Отопление' },
        climate: { icon: 'fa-wind', label: 'Климат / вентиляция' },
        water: { icon: 'fa-faucet-drip', label: 'Водоснабжение' },
        engineeringNode: { icon: 'fa-sliders', label: 'Гидроузел и разводка' },
        drainage: { icon: 'fa-water', label: 'Канализация' },
        smart: { icon: 'fa-microchip', label: 'Умный дом' },
        extras: { icon: 'fa-shield-halved', label: 'Дополнительные решения' }
      };
      return map[blockKey] || { icon: 'fa-puzzle-piece', label: blockKey };
    }

    function renderRepairQuestPuzzleStrip(meta, { mobileSkippedOnly = false } = {}) {
      if (!meta) return '';
      const blocks = getRepairQuestBlockKeys(meta);
      const pieces = blocks
        .map((blockKey, index) => ({
          blockKey,
          index,
          confirmed: isRepairQuestBlockConfirmed(meta.key, blockKey),
          ready: isRepairQuestBlockReady(meta.key, blockKey),
          ...getRepairQuestBlockVisual(blockKey)
        }))
        .filter(piece => !mobileSkippedOnly || !piece.confirmed);

      if (!pieces.length) return mobileSkippedOnly ? '' : '<div class="puzzle-status">Все блоки подтверждены</div>';

      return `
        <div class="puzzle-grid ${mobileSkippedOnly ? 'is-mobile-skipped' : ''}">
          ${pieces.map(piece => {
            const isLastConfirmed = repairQuestState.lastConfirmedBlock?.roomKey === meta.key
              && repairQuestState.lastConfirmedBlock?.blockKey === piece.blockKey;
            return `
            <button type="button" class="puzzle-piece ${piece.confirmed ? 'completed' : 'is-skipped'} ${isLastConfirmed ? 'active' : ''} ${piece.ready && !piece.confirmed ? 'is-ready' : ''}" onclick="jumpToRepairQuestBlock('${meta.key}', '${piece.blockKey}')" title="${piece.label}">
              <div class="puzzle-icon"><i class="fas ${piece.icon}"></i></div>
              <div class="puzzle-label">${piece.index + 1}. ${piece.label}</div>
            </button>
          `;
          }).join('')}
        </div>
      `;
    }

    function renderRepairQuestMobileSkippedPuzzles(meta) {
      if (!meta) return '';
      const html = renderRepairQuestPuzzleStrip(meta, { mobileSkippedOnly: true });
      if (!html) return '';
      return `
        <div class="quest-mobile-skipped-puzzles">
          <div class="quest-mobile-skipped-title">Неподтвержденные блоки</div>
          ${html}
        </div>
      `;
    }

    function renderRepairQuestScene(progress, currentRoom) {
      const blocks = currentRoom ? getRepairQuestBlockKeys(currentRoom) : [];
      const confirmedCount = currentRoom ? blocks.filter(blockKey => isRepairQuestBlockConfirmed(currentRoom.key, blockKey)).length : 0;
      const isComplete = progress >= 1;

      // Выбираем финальное фото на основе стиля дизайна
      const designStyle = currentRoom?.source?.repairData?.designStyle || 'other';
      const villaImageMap = {
        'modern_minimalism': 'Villa_modern_min.jpg',
        'modern_classic': 'Villa_modern_classic.webp',
        'classic': 'Villa_classic.jpg',
        'scandinavian': 'Villa_Scandinavian.png',
        'modern': 'Villa_modern.webp',
        'art_deco': 'Villa_Art-deko.jpg',
        'japanese': 'Villa_Japan.jpg',
        'chinese': 'Villa_China.webp'
      };
      const villaImageName = villaImageMap[designStyle] || 'Villa_other.webp';
      const finalPhotoUrl = `images/${villaImageName}`;

      if (isComplete) {
        ensureRepairQuestConfettiGenerated();
      }
      const confettiHtml = isComplete ? (repairQuestState?.confettiHtml || '') : '';

      return `
        <div class="puzzle-container">
          <div class="confetti-layer">${confettiHtml}</div>
          ${renderRepairQuestPuzzleStrip(currentRoom)}
          <div class="puzzle-status">
            ${isComplete ? 'Пазл собран. Ремонт готов к расчету.' : `Подтверждено блоков: ${confirmedCount}/${blocks.length || 0}`}
          </div>
          ${isComplete ? `
            <div class="puzzle-final">
              <img class="puzzle-final-image" src="${finalPhotoUrl}" alt="Премиальный ремонт" loading="lazy">
              <div class="puzzle-final-copy">
                <div>
                  <h3>Вы справились! Запускаем расчет сметы!</h3>
                  <p>Все этапы проекта собраны. Теперь мы подготовим точную смету для вашего премиального ремонта.</p>
                </div>
              </div>
            </div>
          ` : ''}
        </div>
      `;
    }

    function formatRepairQuestInfoNumber(value, suffix = '') {
      const number = Number(value || 0);
      return `${number.toLocaleString('ru-RU', { maximumFractionDigits: 2 })}${suffix}`;
    }

    function getRepairQuestInfoSurfaceRows(meta, answer = {}) {
      const metrics = getRepairQuestRoomMetrics(meta?.source || {});
      const ceilingDetailParts = [
        ['ceiling_gk', 'ceiling_stretch'].includes(answer.targetCeiling)
          ? `Уровни: ${answer.ceilingLevels === 'multilevel' ? '2+ уровня / короб' : 'один уровень'}`
          : '',
        answer.ceilingLightLines === 'yes' ? 'световые линии: да' : 'световые линии: нет'
      ].filter(Boolean);
      return [
        { key: 'floor', label: 'Пол', area: metrics.floorArea, finish: getRepairFinishingOption('floor', answer.targetFloor)?.label || 'Не выбрано', detail: `Финиш: ${getRepairFinishingOption('floor', answer.targetFloor)?.label || 'не выбран'}. ${isRepairQuestFloorTileTarget(answer) ? `Укладка: ${getRepairQuestFloorLayoutLabel(answer) || 'классическая'}. ` : ''}Размер: ${shouldShowRepairQuestFloorCoverSize(answer) ? `${Number(answer.floorCoverLengthMm || 0).toLocaleString('ru-RU')}x${Number(answer.floorCoverWidthMm || 0).toLocaleString('ru-RU')} см` : 'не задан'}. Бордюр: ${answer.targetFloorBorderEnabled === 'yes' ? formatRepairQuestInfoNumber(answer.targetFloorBorderLength, ' м') : 'нет'}. Декор: ${answer.targetFloorDecorEnabled === 'yes' ? `${answer.targetFloorDecorCount || 0} шт.` : 'нет'}. Теплый пол: ${answer.warmFloor === 'yes' ? formatRepairQuestInfoNumber(getRepairQuestWarmFloorArea(meta, answer), ' м²') : 'нет'}.` },
        { key: 'wall', label: 'Стены', area: metrics.wallArea, finish: getRepairFinishingOption('wall', answer.targetWall)?.label || 'Не выбрано', detail: `Финиш: ${getRepairFinishingOption('wall', answer.targetWall)?.label || 'не выбран'}. ${isRepairQuestWallTileTarget(answer) ? `Укладка: ${getRepairQuestWallLayoutLabel(answer) || 'классическая'}. Размер: ${Number(answer.wallCoverLengthCm || 0).toLocaleString('ru-RU')}x${Number(answer.wallCoverWidthCm || 0).toLocaleString('ru-RU')} см. ` : ''}Плитка: ${answer.tileWallCoverage === 'partial' ? `до ${answer.tileWallPartialHeight || 0} м` : answer.tileWallCoverage === 'full' ? 'до потолка' : 'нет'}.` },
        { key: 'ceiling', label: 'Потолок', area: metrics.ceilingArea, finish: getRepairQuestCeilingInfoLabel(answer), detail: ceilingDetailParts.join('. ') + '.' }
      ];
    }

    function getRepairQuestCeilingInfoLabel(answer = {}) {
      const base = getRepairFinishingOption('ceiling', answer.targetCeiling)?.label || 'Не выбрано';
      if (answer.targetCeiling === 'ceiling_stretch') {
        const type = answer.ceilingStretchType === 'shadow' ? 'теневой / парящий' : 'стандартный';
        const material = answer.ceilingStretchMaterial === 'pvc' ? 'ПВХ / пленка' : 'тканевый';
        return `${base}: ${type}, ${material}`;
      }
      if (answer.targetCeiling === 'ceiling_paint') {
        return `${base}: ${getQuestOptionLabel(repairQuestCeilingPaintFinishOptions, answer.ceilingPaintFinish)}`;
      }
      if (answer.targetCeiling === 'ceiling_gk') {
        const levels = answer.ceilingLevels === 'multilevel' ? '2+ уровня / короб' : 'один уровень';
        const paint = answer.ceilingGkPaint !== 'no'
          ? `, покраска ${getQuestOptionLabel(repairQuestCeilingPaintFinishOptions, answer.ceilingGkPaintFinish)}`
          : '';
        return `${base}: ${levels}${paint}`;
      }
      const detail = getRepairQuestCeilingDetailOptions(answer.targetCeiling).find(option => option.value === answer.targetCeilingDetail)?.label;
      return detail ? `${base}: ${detail}` : base;
    }

    function getRepairQuestInfoElectricalRows(answer = {}) {
      const ledLength = getRepairQuestLedLightingLength(answer);
      return [
        { key: 'lights', icon: 'fa-lightbulb', label: 'Светильники', value: formatRepairQuestInfoNumber(getRepairQuestLightingTotal(answer), ' шт.'), detail: `Точечные: ${answer.spotLights || 0}, люстры/подвесы: ${answer.chandeliers || 0}, бра: ${answer.wallLights || 0}.` },
        { key: 'sockets', icon: 'fa-plug-circle-bolt', label: 'Розетки', value: formatRepairQuestInfoNumber(getRepairQuestTotalSockets(answer), ' шт.'), detail: `Одинарные: ${answer.singleSockets || 0}, двойные: ${answer.doubleSockets || 0}, тройные: ${answer.tripleSockets || 0}, влагозащищенные: ${answer.moistureProofSockets || 0}.` },
        { key: 'switches', icon: 'fa-toggle-on', label: 'Выключатели', value: formatRepairQuestInfoNumber(getRepairQuestSwitchesTotal(answer), ' шт.'), detail: `Одинарные: ${answer.singleSwitches || 0}, двойные: ${answer.doubleSwitches || 0}, мастер-сценарии: ${Number(answer.masterLightSwitches || 0) + Number(answer.masterPowerSwitches || 0)}.` },
        { key: 'led', icon: 'fa-grip-lines', label: 'LED / подсветка', value: formatRepairQuestInfoNumber(ledLength, ' м'), detail: `Потолочные световые линии: ${formatRepairQuestInfoNumber(answer.ledLinesLength, ' м')}, настенный линейный свет: ${formatRepairQuestInfoNumber(answer.wallLinearLightLength, ' м')}, скрытая подсветка потолка: ${formatRepairQuestInfoNumber(answer.ceilingBacklightLength, ' м')}, плинтус: ${formatRepairQuestInfoNumber(answer.plinthBacklightLength, ' м')}.` },
        { key: 'tracks', icon: 'fa-route', label: 'Треки', value: `${formatRepairQuestInfoNumber(answer.trackLights, ' шт.')} · ${formatRepairQuestInfoNumber(answer.ceilingTrackLength, ' м')}`, detail: `Количество трековых светильников/шинопроводов и длина трека синхронизируются с блоком потолка.` },
        { key: 'panel', icon: 'fa-table-columns', label: 'Электрощит', value: answer.electricalPanelHere === 'yes' ? `${answer.electricalPanelModules || 0} мод.` : 'не в комнате', detail: answer.electricalPanelHere === 'yes' ? `Автоматы: ${answer.electricalPanelBreakers || 0}, дифавтоматы: ${answer.electricalPanelDifBreakers || 0}, нагрузка: ${formatRepairQuestInfoNumber(answer.electricalPanelLoadKw, ' кВт')}.` : 'Щит для этого помещения не отмечен.' }
      ];
    }

    function isRepairQuestInfoDetailOpen(id) {
      return Array.isArray(repairQuestState.infoExpandedIds) && repairQuestState.infoExpandedIds.includes(id);
    }

    function renderRepairQuestInfoExpandButton(id) {
      const open = isRepairQuestInfoDetailOpen(id);
      return `<button type="button" class="repair-info-expand" onclick="toggleRepairQuestInfoDetail('${id}')" aria-label="${open ? 'Свернуть детали' : 'Показать детали'}"><i class="fas ${open ? 'fa-minus' : 'fa-plus'}"></i></button>`;
    }

    function renderRepairQuestInfoDetail(id, text) {
      return `<div class="repair-info-detail ${isRepairQuestInfoDetailOpen(id) ? 'is-open' : ''}"><div>${text}</div></div>`;
    }

    function renderRepairQuestInfoPanelRoom(meta, { compact = false } = {}) {
      const answer = repairQuestState.answers?.[meta.key] || {};
      const context = getRepairQuestRoomContext(meta);
      const surfaces = getRepairQuestInfoSurfaceRows(meta, answer);
      const electrical = getRepairQuestInfoElectricalRows(answer);
      const confirmedBlocks = getRepairQuestBlockKeys(meta).filter(blockKey => isRepairQuestBlockConfirmed(meta.key, blockKey)).length;
      const totalBlocks = getRepairQuestBlockKeys(meta).length;
      return `
        <section class="repair-info-room-card ${compact ? 'is-compact' : ''}">
          <div class="repair-info-room-head">
            <div>
              <div class="repair-info-room-title">${meta.title}</div>
              <div class="repair-info-room-subtitle">${context.appointment} · ${context.location}</div>
            </div>
            <span>${confirmedBlocks}/${totalBlocks}</span>
          </div>
          <div class="repair-info-surfaces">
            ${surfaces.map(item => `
              <div class="repair-info-surface">
                <span>${item.label}</span>
                <strong>${formatRepairQuestInfoNumber(item.area, ' м²')}</strong>
                <small>${item.finish}</small>
                ${renderRepairQuestInfoExpandButton(`${meta.key}:surface:${item.key}`)}
                ${renderRepairQuestInfoDetail(`${meta.key}:surface:${item.key}`, item.detail)}
              </div>
            `).join('')}
          </div>
          ${compact ? '' : `
            <div class="repair-info-metrics">
              ${electrical.map(item => `
                <div class="repair-info-metric">
                  <i class="fas ${item.icon}"></i>
                  <span>${item.label}</span>
                  <strong>${item.value}</strong>
                  ${renderRepairQuestInfoExpandButton(`${meta.key}:metric:${item.key}`)}
                  ${renderRepairQuestInfoDetail(`${meta.key}:metric:${item.key}`, item.detail)}
                </div>
              `).join('')}
            </div>
          `}
        </section>
      `;
    }

    function renderRepairQuestInfoPanel() {
      const panel = document.getElementById('repairQuestInfoPanel');
      const backdrop = document.getElementById('repairQuestInfoBackdrop');
      const button = document.getElementById('repairQuestInfoToggle');
      const screen = document.getElementById('repairQuestScreen');
      if (!panel || !repairQuestState) return;
      if (panel.parentElement !== document.body) {
        document.body.appendChild(panel);
      }
      if (backdrop && backdrop.parentElement !== document.body) {
        document.body.appendChild(backdrop);
      }
      const open = !!repairQuestState.infoPanelOpen;
      const currentRoom = repairQuestState.rooms[repairQuestState.step] || repairQuestState.rooms[0];
      const otherRooms = repairQuestState.rooms.filter(room => room.key !== currentRoom?.key);
      panel.innerHTML = `
        <div class="repair-info-panel-head">
          <div>
            <div class="repair-info-kicker">Сводка по квесту</div>
            <h3>Информация по ремонту</h3>
            <p>Площади, отделка и инженерные точки по заполняемым помещениям.</p>
          </div>
          <button type="button" onclick="toggleRepairQuestInfoPanel(false)" aria-label="Закрыть информацию по ремонту">
            <i class="fas fa-xmark"></i>
          </button>
        </div>
        ${currentRoom ? `
          <div class="repair-info-current-label">Текущее помещение</div>
          ${renderRepairQuestInfoPanelRoom(currentRoom)}
        ` : ''}
        ${otherRooms.length ? `
          <div class="repair-info-current-label">Остальные помещения</div>
          <div class="repair-info-room-stack">
            ${otherRooms.map(room => renderRepairQuestInfoPanelRoom(room, { compact: true })).join('')}
          </div>
        ` : ''}
      `;
      panel.classList.toggle('is-open', open);
      panel.setAttribute('role', 'dialog');
      panel.setAttribute('aria-modal', open ? 'true' : 'false');
      panel.setAttribute('aria-hidden', open ? 'false' : 'true');
      backdrop?.classList.toggle('is-open', open);
      button?.classList.toggle('is-active', open);
      screen?.classList.toggle('is-info-open', open);
      document.body.classList.toggle('repair-quest-info-open', open);
    }

    function renderRepairQuestHeaderState() {
      const screen = document.getElementById('repairQuestScreen');
      const compact = !!repairQuestState?.compactHeader;
      screen?.classList.toggle('is-quest-head-compact', compact);
      const toggle = document.getElementById('repairQuestCompactToggle');
      if (toggle) {
        const icon = toggle.querySelector('i');
        const label = toggle.querySelector('span');
        if (icon) icon.className = `fas ${compact ? 'fa-expand' : 'fa-compress'}`;
        if (label) label.textContent = compact ? 'Развернуть' : 'Компактно';
      }
    }

    let repairQuestInfoTouchStartX = 0;
    let repairQuestInfoTouchStartY = 0;

    function bindRepairQuestInfoPanelGestures() {
      const panel = document.getElementById('repairQuestInfoPanel');
      if (!panel || panel.dataset.swipeBound === 'yes') return;
      panel.dataset.swipeBound = 'yes';
      panel.addEventListener('touchstart', event => {
        const touch = event.touches?.[0];
        if (!touch) return;
        repairQuestInfoTouchStartX = touch.clientX;
        repairQuestInfoTouchStartY = touch.clientY;
      }, { passive: true });
      panel.addEventListener('touchend', event => {
        const touch = event.changedTouches?.[0];
        if (!touch) return;
        const dx = touch.clientX - repairQuestInfoTouchStartX;
        const dy = touch.clientY - repairQuestInfoTouchStartY;
        const isSideSwipe = Math.abs(dx) > 72 && Math.abs(dx) > Math.abs(dy) * 1.4;
        const isDownSwipe = dy > 72 && dy > Math.abs(dx) * 1.2;
        if (isSideSwipe || isDownSwipe) {
          toggleRepairQuestInfoPanel(false);
        }
      }, { passive: true });
    }

    window.toggleRepairQuestInfoPanel = toggleRepairQuestInfoPanel;
    window.toggleRepairQuestCompactHeader = toggleRepairQuestCompactHeader;
    window.toggleRepairQuestInfoDetail = toggleRepairQuestInfoDetail;
    window.showRepairQuestPanelModuleInfo = showRepairQuestPanelModuleInfo;
    window.hideRepairQuestPanelModuleInfo = hideRepairQuestPanelModuleInfo;
    window.startRepairQuestPanelModuleSwipe = startRepairQuestPanelModuleSwipe;
    window.endRepairQuestPanelModuleSwipe = endRepairQuestPanelModuleSwipe;

    function renderRepairQuestRoomList() {
      const container = document.getElementById('repairQuestRoomList');
      if (!container) return;

      container.innerHTML = repairQuestState.rooms.map((room, index) => {
        const isCurrent = index === repairQuestState.step;
        const totalBlocks = getRepairQuestBlockKeys(room).length;
        const confirmedBlocks = getRepairQuestBlockKeys(room).filter(blockKey => isRepairQuestBlockConfirmed(room.key, blockKey)).length;
        const isCompleted = totalBlocks > 0 && confirmedBlocks === totalBlocks;
        const context = getRepairQuestRoomContext(room);
        const badge = isCompleted ? '<i class="fas fa-check text-green-500"></i>' : isCurrent ? '<i class="fas fa-hammer text-brand-500"></i>' : `<span class="text-xs text-gray-400">${confirmedBlocks}/${totalBlocks}</span>`;
        return `
          <div class="quest-room-chip ${isCurrent ? 'ring-2 ring-brand-300 dark:ring-brand-700' : ''}">
            <span>${getRepairQuestRoomDisplayName(room)}<span class="block text-xs text-gray-400 mt-1">${getRepairQuestRoomRegistryLine(room)}</span><span class="block text-xs text-gray-400">${context.appointment} · ${context.location}</span><span class="block text-xs text-gray-400">Подтверждено блоков: ${confirmedBlocks}/${totalBlocks}</span></span>
            <span>${badge}</span>
          </div>`;
      }).join('');
    }

    function renderQuestChoiceButtons(roomKey, field, choices, showMode = true) {
      const current = repairQuestState.answers[roomKey]?.[field] || '';
      return `
        ${showMode ? renderQuestChoiceModeBadge('Один вариант', 'fa-circle-dot') : ''}
        <div class="quest-choice-grid">
          ${choices.map(choice => `
            <button type="button" class="quest-choice ${current === choice.value ? 'is-selected' : ''}" onclick="updateRepairQuestAnswer('${roomKey}', '${field}', '${choice.value}')">
              <div class="font-semibold text-sm">${choice.label}</div>
              ${choice.hint ? `<div class="text-xs text-gray-500 mt-1">${choice.hint}</div>` : ''}
            </button>
          `).join('')}
        </div>
      `;
    }

